import java.util.*;

class OrderItem {
    String productId;
    int quantity;
    double unitPrice;

    OrderItem(String productId, int quantity, double unitPrice) {
        this.productId = productId;
        this.quantity = quantity;
        this.unitPrice = unitPrice;
    }
}

class OrderRequest {
    String customerId;
    List<OrderItem> items;

    OrderRequest(String customerId, List<OrderItem> items) {
        this.customerId = customerId;
        this.items = items;
    }
}

class OrderResult {
    boolean success;
    String message;
    double total;

    OrderResult(boolean success, String message, double total) {
        this.success = success;
        this.message = message;
        this.total = total;
    }
}

// service holds the actual business logic
class OrderService {
    private final Map<String, Integer> stockByProduct = new HashMap<>();

    OrderService() {
        // seed some stock for the demo
        stockByProduct.put("SKU-1", 5);
        stockByProduct.put("SKU-2", 0);
    }

    OrderResult processOrder(OrderRequest request) {
        // 1. check stock for every item first, before touching anything else
        for (OrderItem item : request.items) {
            int available = stockByProduct.getOrDefault(item.productId, 0);
            if (available < item.quantity) {
                return new OrderResult(false, "Insufficient stock for " + item.productId, 0.0);
            }
        }

        // 2. calculate the order total, this is the real business rule
        double total = 0.0;
        for (OrderItem item : request.items) {
            total += item.quantity * item.unitPrice;
        }

        // 3. deduct stock only now that the order is confirmed
        for (OrderItem item : request.items) {
            stockByProduct.put(item.productId, stockByProduct.get(item.productId) - item.quantity);
        }

        return new OrderResult(true, "Order placed successfully", total);
    }
}

// controller stays thin, it only receives the request and delegates
class OrderController {
    private final OrderService orderService = new OrderService();

    OrderResult placeOrder(OrderRequest request) {
        // no business logic here at all, just forward to the service
        return orderService.processOrder(request);
    }
}

public class Main {
    public static void main(String[] args) {
        OrderController controller = new OrderController();

        List<OrderItem> items = new ArrayList<>();
        items.add(new OrderItem("SKU-1", 2, 19.99));

        OrderRequest request = new OrderRequest("cust-42", items);
        OrderResult result = controller.placeOrder(request);

        System.out.println(result.message + ", total=" + result.total);
    }
}

