#include <bits/stdc++.h>
using namespace std;

struct OrderItem {
    string productId;
    int quantity;
    double unitPrice;
};

struct OrderRequest {
    string customerId;
    vector<OrderItem> items;
};

struct OrderResult {
    bool success;
    string message;
    double total;
};

// service holds the actual business logic
class OrderService {
    unordered_map<string, int> stockByProduct;
public:
    OrderService() {
        // seed some stock for the demo
        stockByProduct["SKU-1"] = 5;
        stockByProduct["SKU-2"] = 0;
    }

    OrderResult processOrder(const OrderRequest& request) {
        // 1. check stock for every item first, before touching anything else
        for (const auto& item : request.items) {
            int available = stockByProduct.count(item.productId) ? stockByProduct[item.productId] : 0;
            if (available < item.quantity) {
                return {false, "Insufficient stock for " + item.productId, 0.0};
            }
        }

        // 2. calculate the order total, this is the real business rule
        double total = 0.0;
        for (const auto& item : request.items) {
            total += item.quantity * item.unitPrice;
        }

        // 3. deduct stock only now that the order is confirmed
        for (const auto& item : request.items) {
            stockByProduct[item.productId] -= item.quantity;
        }

        return {true, "Order placed successfully", total};
    }
};

// controller stays thin, it only receives the request and delegates
class OrderController {
    OrderService orderService;
public:
    OrderResult placeOrder(const OrderRequest& request) {
        // no business logic here at all, just forward to the service
        return orderService.processOrder(request);
    }
};

int main() {
    OrderController controller;

    vector<OrderItem> items = { {"SKU-1", 2, 19.99} };
    OrderRequest request{"cust-42", items};
    OrderResult result = controller.placeOrder(request);

    cout << result.message << ", total=" << result.total << endl;
    return 0;
}
